const R = process.argv[2];
const O = process.argv[3];
const load = async (root, name) => (await import(`file://${root}/src/handlers/${name}.js`))[name];
const { createStore } = await import(`file://${R}/src/store.js`);
const names = ['createUser', 'updateUser', 'inviteUser'];
const vals = [undefined, null, 5, '', '   ', 'nope', 'a@b', 'Ann@Example.com', ' bob@x.io ', 'ann@example.com', 'x'.repeat(80), 'x'.repeat(81), ' Ann Lee ', 'owner', 'admin', 'viewer', 'god'];
const seed = (s) => { s.addUser({ email: 'ann@example.com', name: 'Ann Lee', role: 'member' }); s.addUser({ email: 'bob@example.com', name: 'Bob', role: 'viewer' }); s.addInvitation({ email: 'inv@example.com', name: '', role: 'member' }); return s; };
let total = 0, diffs = [];
for (const name of names) {
  const oldH = await load(O, name), newH = await load(R, name);
  const keys = name === 'updateUser' ? ['email', 'name', 'role'] : ['email', 'name', 'role'];
  const bodies = [];
  const fieldVals = keys.map(() => vals);
  // every combination of up to 3 fields, each from the value list
  for (const a of vals) for (const b of vals) for (const c of vals) {
    const body = {}; const src = [a, b, c];
    keys.forEach((k, i) => { if (src[i] !== undefined || Math.random() < 0.5) body[k] = src[i]; });
    bodies.push(body);
  }
  bodies.push(undefined, null, {});
  for (const body of bodies) for (const id of ['1', '2', '9']) {
    const req = name === 'updateUser' ? { params: { id }, body } : { body };
    const oldR = oldH(seed(createStore()), req);
    const newR = newH(seed(createStore()), req);
    total++;
    if (JSON.stringify(oldR) !== JSON.stringify(newR)) diffs.push({ name, body, id, old: oldR, new: newR });
  }
}
console.log(`cases=${total} differing=${diffs.length}`);
const seen = new Set();
for (const d of diffs) { const k = d.name + JSON.stringify(d.body); if (seen.has(k) && seen.size > 40) continue; seen.add(k); if (seen.size <= 12) console.log(JSON.stringify(d)); }
EOF
cd "$D" && node "$D/diff.mjs" "$REPO" "$D/old" 2>&1 | head -n 40

